{"command": "cat > /workspace/work/compose.py <<'PYEOF'
import sys, numpy as np
sys.path.insert(0,'/workspace/work')
from xmlib import Song, Instrument, Sample, Pattern, write_xm
import sounds3 as sy

S    = 33452.0
NCYC = 128
REL  = 24      # loop instruments: written C-4 == 261.63 Hz

def norm(x,peak=0.9): return sy.norm(x,peak)
def midi(name):
    names={'C':0,'C#':1,'Db':1,'D':2,'D#':3,'Eb':3,'E':4,'F':5,'F#':6,'Gb':6,
           'G':7,'G#':8,'Ab':8,'A':9,'A#':10,'Bb':10,'B':11}
    body=name[:-1]
    if body[-1]=='-': body=body[:-1]
    return 12*(int(name[-1])+1)+names[body]
def n(m): return m-11          # loop instrument note (C-4=49 == MIDI 60)
def nshot(m): return m-11      # one-shot authored at S: written C-4 = authored pitch
# bell/one-shots play their authored pitch at C-4 (which is MIDI 72 for the pluck);
# we prefer to use explicit octave shifts per instrument, see BELL_SHIFT
def add(p,row,ch,note,ins,vol=64,fx=None,param=0):
    p.set(row,ch,note=note,ins=ins,vol=vol,fx=fx,param=param)

# ---------------------------------------------------------------- waves
def additive(nn,kind,duty=0.5,harm=16): return sy.additive(nn,kind,duty,harm)

wave_lead  = norm(additive(NCYC,'pulse',0.25,14)*0.78 + additive(NCYC,'saw',harm=8)*0.22, 0.50)
wave_harm  = norm(additive(NCYC,'pulse',0.125,12)*0.5 + additive(NCYC,'pulse',0.5,10)*0.5, 0.42)
wave_arp   = norm(additive(NCYC,'pulse',0.125,9), 0.34)
wave_arp2  = norm(additive(NCYC,'pulse',0.25,8), 0.26)
wave_bass  = norm(additive(NCYC,'tri',harm=9)*0.62 + additive(NCYC,'saw',harm=8)*0.38, 0.60)
wave_pad   = norm(additive(NCYC,'saw',harm=10), 0.30)
wave_organ = norm(additive(NCYC,'pulse',0.5,10)*0.55 + additive(NCYC,'saw',harm=6)*0.45, 0.34)
wave_bell  = norm(additive(NCYC,'tri',harm=7)*0.55 + additive(NCYC,'sine',harm=1)*0.45, 0.40)
wave_soft  = norm(additive(NCYC,'tri',harm=6), 0.34)

def loop_inst(name, wave, pan, cycles=2, peak=0.5, env=None, fade=0):
    L=len(wave)
    clean=np.tile(wave,cycles)
    atk=wave*(np.linspace(0,1,L)**0.45)
    pcm=norm(np.concatenate([atk,clean]),peak)
    smp=Sample(name,pcm,loop_start=L,loop_end=L*(1+cycles),relative_note=REL,panning=pan,volume=64)
    ins=Instrument(name,[smp],fadeout=fade)
    if env: ins.vol_env=env; ins.vol_type=1
    return ins

def shot(name,pcm,pan,peak,env=None,fade=0):
    pcm=np.asarray(pcm,float)
    if len(pcm)%2: pcm=np.concatenate([pcm,[0.0]])
    smp=Sample(name,norm(pcm,peak),loop=False,relative_note=REL,panning=pan,volume=64)
    ins=Instrument(name,[smp],fadeout=fade)
    if env: ins.vol_env=env; ins.vol_type=1
    return ins

LEAD_ENV  = [(0,0),(1,62),(10,46),(11,46)]
HARM_ENV  = [(0,0),(1,52),(10,38),(11,38)]
ARP_ENV   = [(0,0),(1,58),(5,40),(6,0)]
ARP2_ENV  = [(0,0),(1,48),(5,30),(6,0)]
BASS_ENV  = [(0,0),(1,64),(7,42),(9,0)]
PAD_ENV   = [(0,0),(10,56),(18,48),(30,44),(31,44)]
ORGAN_ENV = [(0,0),(1,54),(6,24),(7,0)]
BELL_ENV  = [(0,0),(1,60),(10,0)]

NAMES=['lead','harm','arp','arp2','bass','pad1','pad2','pad3','pad4','organ',
       'kick','snare','clap','hatc','hato','crash','riser','bell','shaker','soft']
INSTRUMENTS=[
    loop_inst('lead',  wave_lead,  148, 2, 0.50, LEAD_ENV,  0x1400),
    loop_inst('harm',  wave_harm,  100, 2, 0.40, HARM_ENV,  0x1400),
    loop_inst('arp',   wave_arp,   56,  2, 0.32, ARP_ENV,   0x2400),
    loop_inst('arp2',  wave_arp2,  200, 2, 0.24, ARP2_ENV,  0x2400),
    loop_inst('bass',  wave_bass,  128, 2, 0.58, BASS_ENV,  0x3400),
    loop_inst('pad1',  wave_pad,   24,  2, 0.28, PAD_ENV,   0x00a0),
    loop_inst('pad2',  wave_pad,   96,  2, 0.28, PAD_ENV,   0x00a0),
    loop_inst('pad3',  wave_pad,   160, 2, 0.28, PAD_ENV,   0x00a0),
    loop_inst('pad4',  wave_pad,   232, 2, 0.28, PAD_ENV,   0x00a0),
    loop_inst('organ', wave_organ, 136, 2, 0.30, ORGAN_ENV, 0x2000),
    shot('kick',  sy.kick(),   128, 0.94),
    shot('snare', sy.snare(),  120, 0.66),
    shot('clap',  sy.clap(),   108, 0.50),
    shot('hatc',  sy.hat(),    184, 0.34),
    shot('hato',  sy.openhat(),180, 0.28),
    shot('crash', sy.crash(),  120, 0.34),
    shot('riser', sy.riser(),  128, 0.30),
    shot('bell',  sy.pluck(),  60,  0.30, BELL_ENV),
    shot('shaker',sy.hat(peak=0.28, decay=0.022, dur=0.09, seed=9), 152, 0.28),
    loop_inst('soft', wave_soft, 128, 2, 0.30, PAD_ENV, 0x0400),
]
IDX={name:i+1 for i,name in enumerate(NAMES)}

CHANNELS=16
CH=dict(lead=0,harm=1,arp=2,arp2=3,bass=4,pad1=5,pad2=6,pad3=7,pad4=8,organ=9,
        kick=10,snare=11,clap=12,hatc=13,hato=14,crash=15)
CH['riser']=15
CH['bell']=9
CH['shaker']=12
CH['soft']=9

# ---------------------------------------------------------------- harmony
# MIDI note numbers
CHORDS = {
 'Am': dict(arp=[57,60,64,69], pad=[57,60,64,69], root=45),
 'F':  dict(arp=[57,60,65,69], pad=[53,57,60,65], root=41),
 'C':  dict(arp=[60,64,67,72], pad=[55,60,64,67], root=48),
 'G':  dict(arp=[59,62,67,71], pad=[55,59,62,67], root=43),
 'Dm': dict(arp=[62,65,69,74], pad=[50,53,57,62], root=38),
 'E':  dict(arp=[59,64,68,71], pad=[52,56,59,64], root=40),
 'Em': dict(arp=[59,64,67,71], pad=[52,55,59,64], root=40),
 'A':  dict(arp=[61,64,69,73], pad=[57,61,64,69], root=45),
}
def chord(name, semis=0):
    d=CHORDS[name]
    return dict(arp=[x+semis for x in d['arp']], pad=[x+semis for x in d['pad']], root=d['root']+semis)

def pad_bar(p, row, name, vol=16, semis=0, keyoff=None, len_rows=None):
    c=chord(name,semis)
    for i,ch_name in enumerate(['pad1','pad2','pad3','pad4']):
        p.set(row, CH[ch_name], note=n(c['pad'][i]), ins=IDX[ch_name], vol=vol)
    if keyoff is not None:
        for ch_name in ['pad1','pad2','pad3','pad4']:
            p.set(keyoff, CH[ch_name], note='off')

def bass_line(p, row, name, vol=44, style='drive', semis=0):
    root=chord(name,semis)['root']; fifth=root+7; octv=root+12
    seq={'drive':[(0,root),(2,root),(4,octv),(6,root),(8,fifth),(10,root),(12,octv),(14,fifth)],
         'pulse':[(i*2,root) for i in range(8)],
         'sparse':[(0,root),(4,root),(8,octv),(12,fifth)],
         'drive2':[(0,root),(2,root),(4,root),(6,octv),(8,root),(10,fifth),(12,root),(14,octv)],
         'run':[(0,root),(2,root),(4,fifth),(6,octv),(8,octv+7),(10,fifth),(12,octv),(14,root+12)],
         'long':[(0,root),(8,fifth)],
         'gallop':[(0,root),(1,root),(4,root),(5,root),(8,root),(9,root),(12,root),(13,root)],
         'oct':[(0,root),(2,octv),(4,root),(6,octv),(8,root),(10,octv),(12,root),(14,octv)],
         }[style]
    for dr,nt in seq:
        p.set(row+dr, CH['bass'], note=n(nt), ins=IDX['bass'], vol=vol)

def arp_bar(p, row, name, mode='up', step=2, vol=28, ch='arp', semis=0, rows=16, start=0):
    a=chord(name,semis)['arp']
    pats={'up':[a[0],a[1],a[2],a[3]],
          'down':[a[3],a[2],a[1],a[0]],
          'updown':[a[0],a[1],a[2],a[3],a[2],a[1]],
          'oct':[a[0],a[0]+12,a[1],a[1]+12,a[2],a[2]+12,a[3],a[3]+12],
          'oct2':[a[0],a[1],a[2],a[3],a[0]+12,a[1]+12,a[2]+12,a[3]+12],
          'pump':[a[0],a[2],a[1],a[3]],
          'wide':[a[0],a[3],a[1],a[2]],
          'up16':[a[0],a[1],a[2],a[3],a[0],a[1],a[2],a[3],a[0],a[1],a[2],a[3],a[0],a[1],a[2],a[3]]}
    pat=pats[mode]; k=start
    for dr in range(0,rows,step):
        p.set(row+dr, CH[ch], note=n(pat[k%len(pat)]), ins=IDX[ch], vol=vol)
        k+=1
    return k

def organ_stabs(p, row, name, vol=22, semis=0, rhythm=(2,6,10,14), note_sel='root12', cut=2):
    c=chord(name,semis); root=c['root']; fifth=root+7
    sel={'root12':root+12,'fifth12':fifth+12,'root':root,'third':c['pad'][1]}[note_sel]
    for dr in rhythm:
        p.set(row+dr, CH['organ'], note=n(sel), ins=IDX['organ'], vol=vol)
        p.set(row+dr, CH['organ'], fx=0xE, param=0xC0|cut)

def lead_phrase(p, phrase, vol=44, ch='lead', semis=0, ins=None):
    inst=IDX[ins or ch]
    starts=set(r for r,_,_ in phrase)
    for row,note,length in phrase:
        p.set(row, CH[ch], note=n(note+semis), ins=inst, vol=vol)
        if row+length not in starts:
            p.set(row+length, CH[ch], note='off')

def harm_phrase(p, phrase, shift=-12, vol=30, semis=0):
    starts=set(r for r,_,_ in phrase)
    for row,note,length in phrase:
        p.set(row, CH['harm'], note=n(note+shift+semis), ins=IDX['harm'], vol=vol)
        if row+length not in starts:
            p.set(row+length, CH['harm'], note='off')

def drums(p, row, style='full', vol=1.0, crash=False, fill=None, fill_start=56, chord_rows=16):
    def v(x): return max(1,min(64,int(round(x*vol))))
    if crash: p.set(row, CH['crash'], note=n(72), ins=IDX['crash'], vol=v(26))
    blocks=64//chord_rows
    for b in range(blocks):
        r0=row+b*chord_rows
        if style=='full':
            for dr in (0,4,8,12): p.set(r0+dr, CH['kick'], note=n(72), ins=IDX['kick'], vol=v(50))
            for dr in (4,12):     p.set(r0+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(38))
            for dr in range(0,chord_rows,2):
                if dr in (6,14): p.set(r0+dr, CH['hato'], note=n(72), ins=IDX['hato'], vol=v(20))
                else:            p.set(r0+dr, CH['hatc'], note=n(72), ins=IDX['hatc'], vol=v(18 if dr%4==0 else 12))
        elif style=='chorus':
            for dr in (0,4,8,12): p.set(r0+dr, CH['kick'], note=n(72), ins=IDX['kick'], vol=v(52))
            for dr in (4,12):
                p.set(r0+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(40))
                p.set(r0+dr, CH['clap'],  note=n(72), ins=IDX['clap'],  vol=v(28))
            for dr in range(0,chord_rows,2):
                if dr in (6,14): p.set(r0+dr, CH['hato'], note=n(72), ins=IDX['hato'], vol=v(22))
                else:            p.set(r0+dr, CH['hatc'], note=n(72), ins=IDX['hatc'], vol=v(20 if dr%4==0 else 13))
        elif style=='light':
            for dr in (0,8): p.set(r0+dr, CH['kick'], note=n(72), ins=IDX['kick'], vol=v(40))
            for dr in (4,12):p.set(r0+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(26))
            for dr in range(0,chord_rows,4):
                p.set(r0+dr, CH['hatc'], note=n(72), ins=IDX['hatc'], vol=v(14))
        elif style=='half':
            for dr in (0,8): p.set(r0+dr, CH['kick'], note=n(72), ins=IDX['kick'], vol=v(44))
            for dr in (4,12):p.set(r0+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(30))
            for dr in range(0,chord_rows,2):
                p.set(r0+dr, CH['hatc'], note=n(72), ins=IDX['hatc'], vol=v(12))
        elif style=='break':
            for dr in (0,8): p.set(r0+dr, CH['kick'], note=n(72), ins=IDX['kick'], vol=v(38))
            for dr in (4,12):p.set(r0+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(28))
        elif style=='none':
            pass
    if fill is not None:
        for i,dr in enumerate(range(fill_start,fill_start+8)):
            p.set(row+dr, CH['snare'], note=n(72), ins=IDX['snare'], vol=v(20+i*4))

def snare_roll(p, start, end, v0=14, v1=40, step=1, ch='snare'):
    rows=list(range(start,end,step))
    for i,r in enumerate(rows):
        vol=int(v0+(v1-v0)*i/max(1,len(rows)-1))
        p.set(r, CH[ch], note=n(72), ins=IDX[ch], vol=vol)

def riser(p,row,vol=28):
    p.set(row, CH['riser'], note=n(72), ins=IDX['riser'], vol=vol)
