        elif style=='drive':
            seq=[(0,r),(2,r),(4,r+12),(6,r),(8,r+7),(10,r),(12,r+12),(14,r+7)]
        elif style=='gallop':
            seq=[(0,r),(1,r),(3,r),(4,r),(6,r),(8,r),(9,r),(11,r),(12,r),(14,r)]
        elif style=='half':
            seq=[(0,r),(8,r+7)]
        elif style=='long':
            seq=[(0,r)]
        elif style=='oct':
            seq=[(0,r),(2,r+12),(4,r),(6,r+12),(8,r+7),(10,r),(12,r+12),(14,r+7)]
        elif style=='run':
            seq=[(0,r),(2,r),(4,r+7),(6,r+12),(8,r+12),(10,r+7),(12,r+12),(14,r+19)]
        elif style=='pump':
            seq=[(0,r),(3,r),(4,r),(7,r),(8,r),(11,r),(12,r),(15,r)]
        for dr,nt in seq:
            self.put(row+dr,'bass',note=n(nt),ins='bass',vol=vol)
