        a=cd(chord,shift)['arp']
        pats={'up':[a[0],a[1],a[2],a[3]],
              'down':[a[3],a[2],a[1],a[0]],
              'updown':[a[0],a[1],a[2],a[3],a[2],a[1]],
              'wide':[a[0],a[2],a[1],a[3]],
              'oct':[a[0],a[0]+12,a[1],a[1]+12,a[2],a[2]+12,a[3],a[3]+12],
              'octup':[a[0],a[1],a[2],a[3],a[0]+12,a[1]+12,a[2]+12,a[3]+12],
              'pump':[a[0],a[2],a[1],a[3],a[0],a[2],a[3],a[1]],
              'up2':[a[0],a[1],a[2],a[3],a[1],a[2]]}
        pat=pats[mode]; k=start
        for dr in range(0,rows,step):
            self.put(row+dr,ch,note=n(pat[k%len(pat)]),ins=ch,vol=vol)
            k+=1
        return k
    def organ(self,row,chord,vol=15,shift=0,rhythm=(2,6,10,14),sel='third'):
        c=cd(chord,shift)
        note={'root':c['root'],'third':c['third'],'root12':c['root']+12,'fifth':c['root']+7}[sel]
        for dr in rhythm:
            self.put(row+dr,'organ',note=n(note),ins='organ',vol=vol,fx=0xE,param=0xC1)
    def drums(self,row,style='full',vol=1.0,crash=False,chord_rows=16,fill=False,fill_at=None):
        def v(x): return max(1,min(64,int(round(x*vol))))
        if crash: self.put(row,'crash',note=n(72),ins='crash',vol=v(26))
        blocks=64//chord_rows
        for b in range(blocks):
            r0=row+b*chord_rows
            if style in ('full','chorus','drive'):
                for dr in (0,4,8,12):
                    self.put(r0+dr,'kick',note=n(72),ins='kick',vol=v(48))
                for dr in (4,12):
                    self.put(r0+dr,'snare',note=n(72),ins='snare',vol=v(34))
                if style=='chorus':
                    for dr in (4,12):
                        self.put(r0+dr,'clap',note=n(72),ins='clap',vol=v(24))
                hstep=2
                if style=='drive': hstep=1
                for dr in range(0,chord_rows,hstep):
                    if dr in (6,14):
                        self.put(r0+dr,'hato',note=n(72),ins='hato',vol=v(18))
                    else:
                        self.put(r0+dr,'hatc',note=n(72),ins='hatc',vol=v(16 if dr%4==0 else 11))
                if style=='drive':
                    for dr in range(1,chord_rows,4):
                        self.put(r0+dr,'shaker',note=n(72),ins='shaker',vol=v(10))
            elif style=='half':
                for dr in (0,8): self.put(r0+dr,'kick',note=n(72),ins='kick',vol=v(44))
                for dr in (4,12): self.put(r0+dr,'snare',note=n(72),ins='snare',vol=v(28))
                for dr in range(0,chord_rows,2):
                    self.put(r0+dr,'hatc',note=n(72),ins='hatc',vol=v(11))
            elif style=='light':
                for dr in (0,8): self.put(r0+dr,'kick',note=n(72),ins='kick',vol=v(38))
                for dr in (4,12): self.put(r0+dr,'snare',note=n(72),ins='snare',vol=v(24))
                for dr in range(0,chord_rows,4):
                    self.put(r0+dr,'hatc',note=n(72),ins='hatc',vol=v(12))
            elif style=='sparse':
                for dr in (0,): self.put(r0+dr,'kick',note=n(72),ins='kick',vol=v(34))
                for dr in range(0,chord_rows,4):
                    self.put(r0+dr,'hatc',note=n(72),ins='hatc',vol=v(9))
            elif style=='break':
                pass
        if fill:
            at = fill_at if fill_at is not None else row+chord_rows*blocks-8
            for i,dr in enumerate(range(at,at+8)):
                self.put(dr,'snare',note=n(72),ins='snare',vol=v(20+i*4))
    def snare_roll(self,start,end,v0=12,v1=40,step=1,every=1):
        rows=list(range(start,end,step))
        for i,r in enumerate(rows):
            if i%every: continue
            vol=int(v0+(v1-v0)*i/max(1,len(rows)-1))
            self.put(r,'snare',note=n(72),ins='snare',vol=vol)
    def phrase(self,row,notes,vol=44,ch='lead',shift=0,ins=None,harm=False,harm_vol=28):
        inst=ins or ch
        starts=set(r for r,_,_ in notes)
        for r,m,ln in notes:
            self.put(row+r,ch,note=n(m+shift),ins=inst,vol=vol)
            if r+ln not in starts:
                self.put(row+r+ln,ch,note='off')
        if harm:
            hstarts=set(r for r,_,_ in notes)
            for r,m,ln in notes:
                self.put(row+r,'harm',note=n(harmonize(m+shift)),ins='harm',vol=harm_vol)
                if r+ln not in hstarts:
                    self.put(row+r+ln,'harm',note='off')
    def riser(self,row,vol=24):
        self.put(row,'riser',note=n(72),ins='riser',vol=vol)
    def bell_note(self,row,m,vol=22,length=None):
        self.put(row,'bell',note=n(m),ins='bell',vol=vol)
