        if keyoff is not None:
            for nm_ in ['pad1','pad2','pad3','pad4']:
                self.put(keyoff,nm_,note='off')
    def bass(self,row,chord,vol=44,shift=0,style='8ths'):
        r=cd(chord,shift)['root']
        if style=='8ths':
            seq=[(0,r),(2,r),(4,r),(6,r+12),(8,r),(10,r),(12,r+12),(14,r+7)]
        elif style=='drive':
            seq=[(0,r),(2,r),(4,r+12),(6,r),(8,r+7),(10,r),(12,r+12),(14,r+7)]
        elif style=='gallop':
            seq=[(0,r),(1,r),(3,r),(4,r),(6,r),(8,r),(9,r),(11,r),(12,r),(14,r)]
        elif style=='half':
            seq=[(0,r),(8,r+7)]
        elif style=='long':
