        elif style=='run':
            seq=[(0,r),(2,r),(4,r+7),(6,r+12),(8,r+12),(10,r+7),(12,r+12),(14,r+19)]
        elif style=='pump':
            seq=[(0,r),(3,r),(4,r),(7,r),(8,r),(11,r),(12,r),(15,r)]
