            elif style=='light':
                for dr in (0,8): self.put(r0+dr,'kick',note=n(72),ins='kick',vol=v(38))
                for dr in (4,12): self.put(r0+dr,'snare',note=n(72),ins='snare',vol=v(24))
                for dr in range(0,chord_rows,4):
                    self.put(r0+dr,'hatc',note=n(72),ins='hatc',vol=v(12))
            elif style=='sparse':
